<?php

declare(strict_types=1);

namespace Zana\Ddd\Domain;

/**
 * RFC 9562 UUIDs.
 */
final class Uuid
{
    private const PATTERN = '/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i';

    private static int $lastMilliseconds = 0;

    private static int $lastCounter = 0;

    /**
     * A version 7 UUID: a 48-bit millisecond timestamp followed by random bits.
     *
     * UUIDs generated by one process are strictly increasing: within the same
     * millisecond the 12-bit rand_a field acts as a counter.
     */
    public static function v7(): string
    {
        $milliseconds = (int) floor(microtime(true) * 1000);
        $random = random_bytes(10);

        if ($milliseconds <= self::$lastMilliseconds) {
            $milliseconds = self::$lastMilliseconds;
            $counter = self::$lastCounter + 1;
            if ($counter > 0xFFF) {
                $milliseconds++;
                $counter = 0;
            }
        } else {
            $counter = (ord($random[0]) << 4 | ord($random[1]) >> 4) & 0x7FF; // leave room to count up
        }

        self::$lastMilliseconds = $milliseconds;
        self::$lastCounter = $counter;

        $time = str_pad(dechex($milliseconds), 12, '0', STR_PAD_LEFT);
        $tail = bin2hex(substr($random, 2));
        $variant = dechex((hexdec($tail[0]) & 0x3) | 0x8);

        return sprintf(
            '%s-%s-7%03x-%s%s-%s',
            substr($time, 0, 8),
            substr($time, 8, 4),
            $counter,
            $variant,
            substr($tail, 1, 3),
            substr($tail, 4, 12)
        );
    }

    /**
     * Whether the string is an RFC 9562 UUID (versions 1 to 8, variant 10xx),
     * or the nil or max UUID.
     */
    public static function isValid(string $uuid): bool
    {
        $lower = strtolower($uuid);

        return preg_match(self::PATTERN, $uuid) === 1
            || $lower === '00000000-0000-0000-0000-000000000000'
            || $lower === 'ffffffff-ffff-ffff-ffff-ffffffffffff';
    }
}
